}

// Dump returns diagnostic information about the connection pool state.
// It includes pool size, active connections per address, and connection health status.
func (p *connPool) Dump() map[string]interface{} {
	dump := map[string]interface{}{
		"pool_size":      p.size,
		"remote_service": p.remoteService,
		"connections":    make(map[string]interface{}),
	}

	connections := dump["connections"].(map[string]interface{})
	p.conns.Range(func(addr, trans interface{}) bool {
		address := addr.(string)
		t := trans.(*transports)

		activeCount := 0
		inactiveCount := 0
		connStates := make([]map[string]interface{}, 0, t.size)

		for i := 0; i < int(t.size); i++ {
			if t.cliTransports[i] == nil {
				inactiveCount++
				connStates = append(connStates, map[string]interface{}{
					"index":  i,
					"status": "nil",
				})
			} else {
				isActive := t.cliTransports[i].(grpc.IsActive).IsActive()
				if isActive {
					activeCount++
					connStates = append(connStates, map[string]interface{}{
						"index":  i,
						"status": "active",
					})
				} else {
					inactiveCount++
					connStates = append(connStates, map[string]interface{}{
						"index":  i,
						"status": "inactive",
					})
				}
			}
		}

		connections[address] = map[string]interface{}{
			"total_slots":    t.size,
			"active_count":   activeCount,
			"inactive_count": inactiveCount,
			"current_index":  atomic.LoadUint32(&t.index),
			"states":         connStates,
		}
		return true
	})

	return dump
}

